<?php
 namespace QQWorld\Catalog\Model\Product\Option\Validator; use QQWorld\Catalog\Model\Product\Option; use Zend_Validate_Exception; class DefaultValidator extends \QQWorld\Framework\Validator\AbstractValidator { protected $productOptionTypes; protected $priceTypes; public function __construct( \QQWorld\Catalog\Model\ProductOptions\ConfigInterface $productOptionConfig, \QQWorld\Catalog\Model\Config\Source\Product\Options\Price $priceConfig ) { foreach ($productOptionConfig->getAll() as $option) { foreach ($option['types'] as $type) { $this->productOptionTypes[] = $type['name']; } } foreach ($priceConfig->toOptionArray() as $item) { $this->priceTypes[] = $item['value']; } } public function isValid($value) { $messages = []; if (!$this->validateOptionRequiredFields($value)) { $messages['option required fields'] = 'Missed values for option required fields'; } if (!$this->validateOptionType($value)) { $messages['option type'] = 'Invalid option type'; } if (!$this->validateOptionValue($value)) { $messages['option values'] = 'Invalid option value'; } $this->_addMessages($messages); return empty($messages); } protected function validateOptionRequiredFields(Option $option) { $storeId = \QQWorld\Store\Model\Store::DEFAULT_STORE_ID; $product = $option->getProduct(); if ($product) { $storeId = $product->getStoreId(); } $title = $option->getTitle(); return $this->isValidOptionTitle($title, $storeId) && !$this->isEmpty($option->getType()); } protected function isValidOptionTitle($title, $storeId) { if ($storeId > \QQWorld\Store\Model\Store::DEFAULT_STORE_ID && $title === null) { return true; } if ($this->isEmpty($title)) { return false; } return true; } protected function validateOptionType(Option $option) { return $this->isInRange($option->getType(), $this->productOptionTypes); } protected function validateOptionValue(Option $option) { return $this->isInRange($option->getPriceType(), $this->priceTypes) && !$this->isNegative($option->getPrice()); } protected function isEmpty($value) { return empty($value); } protected function isInRange($value, array $range) { return in_array($value, $range); } protected function isNegative($value) { return intval($value) < 0; } } 